sys_ux_data_broker_scriptlet.script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var result = [];

    // Tìm schedule có tên 'JP Holiday'
    var scheduleGR = new GlideRecord('cmn_schedule');
    scheduleGR.addQuery('name', 'JP Holiday');
    scheduleGR.query();

    if (scheduleGR.next()) {
        var scheduleId = scheduleGR.getUniqueValue();

        var spanGR = new GlideRecord('cmn_schedule_span');
        spanGR.addQuery('schedule', scheduleId);
        spanGR.orderBy('start_date_time');
        spanGR.query();

        while (spanGR.next()) {
            result.push({
                name: spanGR.getValue('name'),
                start: spanGR.getDisplayValue('start_date_time'),
                end: spanGR.getDisplayValue('end_date_time'),
                type: spanGR.getValue('type')
            });
        }
    } else {
        response.setStatus(404);
        return { error: "Schedule 'JP Holiday' not found" };
    }

    return result;

})(request, response);
